#!/usr/bin/env python3
# Generated by Claude Sonnet 4.5
"""Export YouTube channel analytics via YouTube Analytics API."""

import csv
import sys
from datetime import datetime, timedelta
from pathlib import Path

# Add parent directory to path for imports
sys.path.insert(0, str(Path(__file__).parent.parent))

from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import build

# Scopes required for YouTube Analytics
SCOPES = [
    "https://www.googleapis.com/auth/youtube.readonly",
    "https://www.googleapis.com/auth/yt-analytics.readonly",
]


def get_authenticated_service():
    """Authenticate with YouTube Analytics API.

    Returns:
        Authenticated YouTube Analytics API service
    """
    # Check if we have stored credentials
    token_file = Path("data/youtube_analytics_token.json")
    credentials = None

    if token_file.exists():
        credentials = Credentials.from_authorized_user_file(str(token_file), SCOPES)

    # If no valid credentials, run OAuth flow
    if not credentials or not credentials.valid:
        flow = InstalledAppFlow.from_client_secrets_file(
            "data/youtube_client_secret.json",  # Download from Google Cloud Console
            SCOPES
        )
        credentials = flow.run_local_server(port=0)

        # Save credentials for next run
        token_file.parent.mkdir(parents=True, exist_ok=True)
        with token_file.open('w') as f:
            f.write(credentials.to_json())

    return build("youtubeAnalytics", "v2", credentials=credentials)


def export_channel_analytics(start_date: str, end_date: str, output_file: str = "youtube_channel_analytics.csv"):
    """Export channel-level analytics.

    Args:
        start_date: Start date (YYYY-MM-DD)
        end_date: End date (YYYY-MM-DD)
        output_file: Output CSV file path
    """
    service = get_authenticated_service()

    # Query channel analytics
    response = service.reports().query(
        ids="channel==MINE",
        startDate=start_date,
        endDate=end_date,
        metrics="views,estimatedMinutesWatched,averageViewDuration,subscribersGained,subscribersLost",
        dimensions="day",
        sort="day"
    ).execute()

    # Write to CSV
    output_path = Path(output_file)
    with output_path.open('w', newline='', encoding='utf-8') as csvfile:
        writer = csv.writer(csvfile)

        # Write header
        headers = ["Date", "Views", "Watch Time (mins)", "Avg View Duration", "Subscribers Gained", "Subscribers Lost"]
        writer.writerow(headers)

        # Write data
        for row in response.get("rows", []):
            writer.writerow(row)

    print(f"✓ Exported channel analytics to {output_path.absolute()}")
    print(f"  Date range: {start_date} to {end_date}")
    print(f"  Total rows: {len(response.get('rows', []))}")


def export_video_analytics(start_date: str, end_date: str, output_file: str = "youtube_video_analytics.csv"):
    """Export per-video analytics.

    Args:
        start_date: Start date (YYYY-MM-DD)
        end_date: End date (YYYY-MM-DD)
        output_file: Output CSV file path
    """
    service = get_authenticated_service()

