def export_search_terms(start_date: str, end_date: str, output_file: str = "youtube_search_terms.csv"):
    """Export YouTube search terms that led viewers to your videos.

    Args:
        start_date: Start date (YYYY-MM-DD)
        end_date: End date (YYYY-MM-DD)
        output_file: Output CSV file path
    """
    service = get_authenticated_service()

    # Query search terms
    # Note: This requires specific filters
    response = service.reports().query(
        ids="channel==MINE",
        startDate=start_date,
        endDate=end_date,
        metrics="views",
        dimensions="insightTrafficSourceDetail",
        filters="insightTrafficSourceType==YT_SEARCH",
        sort="-views",
        maxResults=100
    ).execute()

    # Write to CSV
    output_path = Path(output_file)
    with output_path.open('w', newline='', encoding='utf-8') as csvfile:
        writer = csv.writer(csvfile)

        # Write header
        headers = ["Search Term", "Views"]
        writer.writerow(headers)

        # Write data
        for row in response.get("rows", []):
            writer.writerow(row)

    print(f"✓ Exported search terms to {output_path.absolute()}")
    print(f"  Date range: {start_date} to {end_date}")
    print(f"  Total search terms: {len(response.get('rows', []))}")


def main():
    """Main entry point."""
    # Default: Last 90 days
    end_date = datetime.now().strftime("%Y-%m-%d")
    start_date = (datetime.now() - timedelta(days=90)).strftime("%Y-%m-%d")

    print("=" * 60)
    print("YouTube Analytics Export")
    print("=" * 60)
    print(f"Date range: {start_date} to {end_date}")
    print()

    try:
        # Export all analytics
        export_channel_analytics(start_date, end_date)
        print()

        export_video_analytics(start_date, end_date)
        print()

        export_traffic_sources(start_date, end_date)
        print()

        export_search_terms(start_date, end_date)
        print()

        print("=" * 60)
        print("✓ All exports complete!")
        print("=" * 60)

    except Exception as e:
        print(f"✗ Error: {e}")
        print()
        print("Make sure you have:")
        print("  1. Enabled YouTube Data API v3 in Google Cloud Console")
        print("  2. Downloaded OAuth 2.0 client secrets to data/youtube_client_secret.json")
        print("  3. Run 'uv add google-api-python-client google-auth-oauthlib'")
        sys.exit(1)


if __name__ == "__main__":
    main()
